<script setup>
import {Head,router,useForm} from '@inertiajs/vue3'
import AppLayout from '../../../Layouts/AppLayout.vue'
const p=defineProps({groups:Object,branding:Object})
const labels={general:'عمومی',branding:'برندینگ',learning:'آموزش',video:'ویدیو',sessions:'نشست‌ها',assignments:'تکالیف',qa:'پرسش و پاسخ',notifications:'اعلان‌ها'}
const forms={}
for(const [group,items] of Object.entries(p.groups)) forms[group]=useForm(Object.fromEntries(items.map(i=>[i.key,i.value])))
const save=group=>forms[group].put(`/admin/settings/${group}`)
const reset=group=>{if(confirm('تنظیمات این بخش به مقادیر پیش‌فرض بازگردد؟'))router.delete(`/admin/settings/${group}`)}
const logo=useForm({logo:null})
const uploadLogo=()=>logo.post('/admin/settings/branding/logo',{forceFormData:true})
</script>
<template><AppLayout><Head title="تنظیمات سامانه"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-6"><h1 class="text-2xl font-bold">تنظیمات سامانه</h1><p class="mt-2 text-sm text-slate-500">این بخش فقط تنظیمات محصول را مدیریت می‌کند؛ تنظیمات سرور و اطلاعات محرمانه در دسترس نیستند.</p></section>
<section class="rounded-2xl border bg-white p-5"><h2 class="text-lg font-bold">برندینگ</h2><div class="mt-4 flex flex-wrap items-center gap-4"><img v-if="branding.logo_url" :src="branding.logo_url" alt="لوگوی فعلی" class="h-20 w-20 rounded-xl object-contain"><form class="space-y-2" @submit.prevent="uploadLogo"><input type="file" accept="image/jpeg,image/png,image/webp" @change="logo.logo=$event.target.files[0]"><p class="text-xs text-slate-500">PNG، JPEG یا WebP؛ حداکثر ۲ مگابایت. SVG و فایل اجرایی پذیرفته نمی‌شود.</p><p class="text-sm text-red-600">{{logo.errors.logo}}</p><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">بارگذاری لوگو</button></form></div></section>
<section v-for="(items,group) in groups" :key="group" class="rounded-2xl border bg-white p-5"><h2 class="text-lg font-bold">{{labels[group]||group}}</h2><form class="mt-4 grid gap-4 md:grid-cols-2" @submit.prevent="save(group)"><div v-for="item in items" :key="item.key" :class="{'md:col-span-2':item.key==='institute_address'||item.key==='footer_text'}"><label class="font-medium">{{item.label}}</label><label v-if="item.type==='boolean'" class="mt-2 flex items-center gap-2"><input v-model="forms[group][item.key]" type="checkbox"><span>فعال</span></label><textarea v-else-if="item.key==='institute_address'||item.key==='footer_text'" v-model="forms[group][item.key]" rows="3" class="w-full rounded-xl border p-3"></textarea><input v-else v-model="forms[group][item.key]" :type="item.type==='integer'?'number':item.key==='support_email'?'email':'text'"><p class="mt-1 text-xs text-slate-500">{{item.description}}</p><p class="text-sm text-red-600">{{forms[group].errors[item.key]}}</p></div><div class="flex gap-3 md:col-span-2"><button :disabled="forms[group].processing" class="rounded-xl bg-teal-700 px-4 py-2 text-white">ذخیره این بخش</button><button type="button" class="rounded-xl border px-4 py-2 text-red-700" @click="reset(group)">بازگشت به پیش‌فرض</button></div></form></section>
<section class="rounded-xl bg-amber-50 p-4 text-sm">افزایش سقف فایل در این صفحه، محدودیت‌های PHP، Apache/Nginx یا زیرساخت میزبان را تغییر نمی‌دهد.</section></div></AppLayout></template>
